def transform(grid):
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(r.count(x) for r in grid))
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find the contiguous horizontal pattern and the separate marker color.
    for row in grid:
        runs=[]; cur=[]
        for v in row:
            if v == bg:
                if cur: runs.append(cur); cur=[]
            else: cur.append(v)
        if cur: runs.append(cur)
        run=max(runs, key=len)
        if len(run)>1: break
    marker = next(v for v in set(x for row in grid for x in row) if v not in (bg, *run))
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v == marker:
                left = c - len(run)//2
                for j,x in enumerate(run):
                    if 0 <= left+j < w: out[r][left+j] = x
    return out
